  tools.exec_command({"cmd":"PYTHONPATH=model_training/src python3 -c 'import gzip,json; from robot_observability.metrics import answer_contract_error; p=\"docs/submission/evaluation/source/opentslm.jsonl.gz\"; rows=[json.loads(x) for x in gzip.open(p,\"rt\",encoding=\"utf-8\")]; print(\"\\n\".join(json.dumps({\"record_id\":r[\"record_id\"],\"prediction\":r.get(\"prediction\"),\"target\":r[\"target\"]},sort_keys=True) for r in rows if answer_contract_error(r[\"target\"],r.get(\"prediction\"))==\"invalid_evidence_end_ms_type\"))'","workdir":"/private/tmp/trace-model-reliability","yield_time_ms":30000,"max_output_tokens":12000}),
  tools.exec_command({"cmd":"sed -n '1,180p' docs/submission/evaluation/source/opentslm-metrics.json; sed -n '1,160p' docs/submission/evaluation/source/dataset-summary.json; sed -n '1,220p' model_training/scripts/post_training.py","workdir":"/private/tmp/trace-model-reliability","yield_time_ms":30000,"max_output_tokens":20000}),
  tools.exec_command({"cmd":"git diff --check; PYTHONPATH=model_training/src python3 -m pytest model_training/tests/test_metrics.py model_training/tests/test_comparison.py model_training/tests/test_qa.py -q","workdir":"/private/tmp/trace-model-reliability","yield_time_ms":30000,"max_output_tokens":14000})
]);
text(r.map((x,i) => `RESULT ${i+1}\n${x.status === "fulfilled" ? x.value.output : String(x.reason)}`).join("\n\n"));

